import {indexSidebar,indexWorkspace,indexInspector} from './index-debug.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=x=>JSON.stringify(x??null,null,2);
const state={view:'flow',flow:null,connection:null,workflow:null,selected:'strategy',selectedLink:null,prompt:null,runs:[],traces:[],left:null,right:null,trace:null,event:0,testInput:'{}',testOutput:'尚未试跑',wikiIndex:null,indexPane:'nodes',indexKind:'all',indexSelection:null,indexDocument:null};
const get=async url=>{const r=await fetch(url),v=await r.json();if(!r.ok)throw Error(v.error||v.message||`HTTP ${r.status}`);return v};
const post=async(url,data)=>{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),v=await r.json();if(!r.ok)throw Error(v.error||v.message||`HTTP ${r.status}`);return v};
function toast(message){const box=$('#toast');box.textContent=message;box.style.display='block';setTimeout(()=>box.style.display='none',3800)}
function stage(id){return state.flow?.stages.find(x=>x.id===id)}
async function refresh(){const [flow,connection,workflow,runData,traceData]=await Promise.all([get('/api/debug/flow'),get('/api/debug/connection'),get('/api/debug/workflow'),get('/api/debug/runs'),get('/api/debug/traces')]);Object.assign(state,{flow,connection,workflow,runs:runData.items,traces:traceData.items});$('#status').textContent=`${connection.model} · ${connection.configured?'已连接':'未配置密钥'}`;if(!state.left&&state.runs.length)state.left=state.runs[0].id;render()}
async function selectStage(id){state.selected=id;state.selectedLink=null;state.prompt=stage(id)?.kind==='model'?await get(`/api/debug/prompt?task=${encodeURIComponent(id)}`):null;const example=state.trace?.events?.find(e=>e.task===id);state.testInput=example?pretty(example.input):'{}';state.testOutput='尚未试跑';render()}
async function loadWikiIndex(term=''){state.wikiIndex=await get(`/api/debug/wiki-index?term=${encodeURIComponent(term)}`);render()}
async function selectIndex(kind,id){state.indexSelection={kind,id};state.indexDocument=null;if(kind==='node'||kind==='profile'){render();state.indexDocument=(await get(`/api/debug/wiki-node?id=${encodeURIComponent(kind==='profile'?'profile_local':id)}`)).markdown}render()}
function sidebar(){if(state.view==='index')return indexSidebar(state.wikiIndex,state.indexKind);const lanes=['经历入库','简历制作'];const groups=lanes.map(lane=>`<div class="side-title">${lane}</div>${state.flow.stages.filter(x=>x.lane===lane).map(x=>`<button class="side-item ${state.selected===x.id?'active':''}" data-stage="${x.id}">${esc(x.label)} <em>${x.kind==='model'?'AI':x.kind==='rule'?'规则':'输入'}</em></button>`).join('')}`).join('');const runList=state.runs.slice(0,12).map(r=>`<button data-run="${esc(r.id)}">${esc(r.jd||r.id)}<small>${esc(r.id)} · ${esc(r.status)}</small></button>`).join('')||'<p class="muted">还没有生成记录</p>';const traceList=state.traces.slice(0,12).map(t=>`<button data-trace="${esc(t.id)}">${esc(t.operation)} · ${t.event_count} 节点<small>${esc(t.at)}${t.error?' · 失败':''}</small></button>`).join('')||'<p class="muted">运行工作台后这里显示轨迹</p>';return state.view==='flow'?groups:state.view==='runs'?`<div class="side-title">最近的 JD 运行</div><div class="run-list">${runList}</div><div class="side-title">逐节点轨迹</div><div class="trace-list">${traceList}</div>`:`<div class="side-title">连接清单</div><p class="muted">工作台 → 本机服务 → DeepSeek 兼容接口</p><p class="muted">Wiki 与简历资料 → 本机 local-data；私有 GitHub 备份在主页面“设置”中触发。</p>`}
function flowCanvas(){const positions={};const lanes=[state.flow.stages.filter(s=>s.lane==='经历入库'),state.flow.stages.filter(s=>s.lane==='简历制作')];lanes[0].forEach((s,i)=>positions[s.id]={x:42+i*245,y:65});lanes[1].forEach((s,i)=>positions[s.id]={x:42+i*190,y:295});const width=Math.max(1880,42+lanes[1].length*190);const links=state.flow.links.map(link=>{const a=positions[link.from],b=positions[link.to];if(!a||!b)return '';const sx=a.x+168,sy=a.y+36,tx=b.x,ty=b.y+36;const d=`M ${sx} ${sy} C ${sx+42} ${sy}, ${tx-42} ${ty}, ${tx} ${ty}`;return `<path data-from="${link.from}" data-to="${link.to}" class="${state.selectedLink?.from===link.from&&state.selectedLink?.to===link.to||state.selected===link.from||state.selected===link.to?'highlight':''}" d="${d}"><title>${esc(link.from)} → ${esc(link.to)}：${esc(link.data)}</title></path>`}).join('');const nodes=state.flow.stages.map(s=>`<button class="flow-node ${s.kind} ${state.selected===s.id?'selected':''}" style="left:${positions[s.id].x}px;top:${positions[s.id].y}px" data-stage="${s.id}"><b>${esc(s.label)}</b><small>${s.kind==='model'?'AI 提示词':s.kind==='rule'?'程序规则':'输入'}</small><span class="dot">${s.kind==='model'?'✧':'●'}</span></button>`).join('');return `<div class="flow-intro"><strong>真实执行链路</strong><div class="muted">点击节点可查看输入输出、连接关系、提示词和试跑入口。连线表示当前程序中的真实数据流；回环代表校验失败后的修复。检索分支可在运行对比中切换。</div></div><div class="flow-surface" style="width:${width}px"><div class="lane-label" style="top:30px">经历入库</div><div class="lane-label" style="top:260px">简历制作</div><svg viewBox="0 0 ${width} 500" preserveAspectRatio="xMinYMin meet">${links}</svg>${nodes}</div>`}
function connectionPanel(){return `<h2 class="panel-title">模型连接</h2><p class="muted">密钥仅保存在本机配置，页面只显示是否已配置。环境变量提供的密钥优先。</p><label class="field"><span>接口地址</span><input id="base-url" value="${esc(state.connection.baseUrl)}"></label><label class="field"><span>模型名称</span><input id="model-name" value="${esc(state.connection.model)}"></label><label class="field"><span>API 密钥（留空则保持原值）</span><input id="api-key" type="password" autocomplete="off" placeholder="${state.connection.configured?'已配置；留空保持':'粘贴密钥'}"></label><button class="primary" data-action="save-connection">保存连接</button><div class="section"><h3>流程规则参数</h3><label class="field"><span>正式生成的默认检索连接</span><select id="default-retrieval">${state.flow.retrieval_modes.map(x=>`<option value="${x.id}" ${state.workflow.default_retrieval_mode===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><label class="field"><input id="repair-on-block" type="checkbox" ${state.workflow.repair_on_block?'checked':''}> 事实校验有阻断时自动修复一次</label><button data-action="save-workflow">保存规则参数</button><p class="muted">保存后，工作台新的正式运行采用这些设置。历史运行不变。</p></div><div class="section"><h3>当前连接</h3><p class="muted">来源：${esc(state.connection.key_source)} · 模型：${esc(state.connection.model)}</p><p class="notice">保存设置不会触发模型请求。可点击任一 AI 节点，填写测试输入后单独试跑。</p></div>`}
function inspector(){if(state.view==='index')return indexInspector(state.wikiIndex,state.indexSelection,state.indexDocument);if(state.view==='connection')return connectionPanel();if(state.view==='flow'&&state.selectedLink){const link=state.selectedLink;return `<h2 class="panel-title">连接：${esc(stage(link.from)?.label)} → ${esc(stage(link.to)?.label)}</h2><p class="muted">这条连接传递的内容与触发条件：</p><div class="link">${esc(link.data)}</div><div class="section"><h3>连接来源</h3><p class="muted">${esc(stage(link.from)?.implementation)} → ${esc(stage(link.to)?.implementation)}</p><p class="muted">${/用户主动/.test(link.data)?'用户主动触发，不会自动执行。':/有 block|无 block|accept=|新建经历/.test(link.data)?'这条连接带有条件，条件由程序校验。':'当前流程中的顺序连接。'}</p>${['experience_search','evaluate','verify','repair'].includes(link.from)||['experience_search','evaluate','verify','repair'].includes(link.to)?'<button data-view="connection">调整检索／修复分支</button>':''}</div>`} if(state.view==='runs'){const trace=state.trace;return `<h2 class="panel-title">运行轨迹</h2><p class="muted">点击左侧轨迹，可看到每次模型调用的完整输入、输出与耗时。</p>${trace?`<p><span class="chip">${esc(trace.operation)}</span> ${esc(trace.id)}</p><div class="section"><h3>节点调用</h3>${(trace.events||[]).map((e,i)=>`<button class="side-item ${state.event===i?'active':''}" data-event="${i}">${esc(e.task)} · ${e.elapsed_ms} ms</button>`).join('')}</div>${trace.events?.[state.event]?`<div class="section"><h3>输入</h3><pre class="json">${esc(pretty(trace.events[state.event].input))}</pre><h3>输出</h3><pre class="json">${esc(pretty(trace.events[state.event].output??trace.events[state.event].error))}</pre><button data-action="copy-event">复制输入到节点测试</button></div>`:''}`:'<div class="notice">选择一条轨迹查看调用细节。</div>'}`}
const s=stage(state.selected),inLinks=state.flow.links.filter(x=>x.to===s.id),outLinks=state.flow.links.filter(x=>x.from===s.id);return `<h2 class="panel-title">${esc(s.label)}</h2><span class="chip ${s.kind==='rule'?'rule':''}">${s.kind==='model'?'AI 节点':s.kind==='rule'?'程序规则':'输入节点'}</span><p class="muted">${esc(s.id)} · ${esc(s.lane)}</p><p class="muted">实现位置：${esc(s.implementation)}</p><div class="section"><h3>数据契约</h3><p><b>输入：</b>${esc(s.input||'用户直接输入')}</p><p><b>输出：</b>${esc(s.output)}</p></div><div class="section"><h3>上游连接</h3>${inLinks.map(x=>`<div class="link"><b>${esc(stage(x.from)?.label)}</b> → 当前节点<small>${esc(x.data)}</small></div>`).join('')||'<p class="muted">入口节点</p>'}<h3>下游连接</h3>${outLinks.map(x=>`<div class="link">当前节点 → <b>${esc(stage(x.to)?.label)}</b><small>${esc(x.data)}</small></div>`).join('')||'<p class="muted">结束节点</p>'}</div>${s.kind==='model'?`<div class="section"><h3>提示词 ${state.prompt?.custom?'<span class="chip">本机自定义</span>':''}</h3><label class="field"><textarea id="prompt" class="prompt">${esc(state.prompt?.prompt||'')}</textarea></label><div class="actions"><button class="primary" data-action="save-prompt">保存新版</button><button data-action="reset-prompt">恢复默认</button></div><details><summary>历史版本</summary>${(state.prompt?.history||[]).map((h,i)=>`<button class="side-item" data-history="${i}">${esc(h.at)} · ${h.prompt.length} 字</button>`).join('')||'<p class="muted">暂无自定义版本</p>'}</details></div><div class="section"><h3>单节点试跑</h3><p class="muted">填写该节点接收的 JSON 对象。可以从真实运行轨迹载入输入。</p><label class="field"><textarea id="test-input">${esc(state.testInput)}</textarea></label><button class="primary" data-action="test-node">运行此节点</button><pre class="json" id="test-output">${esc(state.testOutput)}</pre></div>`:`<div class="section"><h3>实现方式</h3><p class="muted">${s.id==='experience_search'?'按完整 Experience 做候选；索引文本包括其子 Story/Fragment 与 Topic。三种检索模式在“运行对比”切换。':s.id==='wiki_commit'?'核对稳定 ID、归属、引用与 Markdown 锚点；通过后切换快照。':s.id==='save_resume'?'正文通过验证后由工作台保存为本地简历版本。':'这个节点由程序规则执行。它的输入输出可在完整运行结果与轨迹中检查。'}</p></div>`}`}
function runSummary(run){if(!run)return '<p class="muted">选择一条运行记录</p>';return `<p><b>${esc(run.id)}</b> · ${esc(run.status)} · ${esc(run.mode)}</p><p>${esc(run.jd?.slice(0,200))}</p><details open><summary>检索与证据</summary><pre class="json">${esc(pretty({query_plan:run.query_plan,discovery:run.discovery,evaluation:run.evaluation}))}</pre></details><details><summary>选材与大纲</summary><pre class="json">${esc(pretty({selection:run.selection,outline:run.outline}))}</pre></details><details><summary>正文与校验</summary><pre class="json">${esc(pretty({content:run.content,validation:run.validation}))}</pre></details><details><summary>完整运行 JSON</summary><pre class="json">${esc(pretty(run))}</pre></details>`}
async function runsView(){const opts=state.runs.map(r=>`<option value="${esc(r.id)}">${esc(r.id)} · ${esc(r.jd.slice(0,55))}</option>`).join('');$('#workspace').innerHTML=`<div class="compare-controls"><b>同一 JD 复跑与比较</b><select id="source-run">${opts}</select><select id="retrieval-mode">${state.flow.retrieval_modes.map(m=>`<option value="${m.id}">${esc(m.label)}</option>`).join('')}</select><label><input id="compose-after" type="checkbox"> 同时生成正文</label><button class="primary" data-action="replay">复跑并对比</button><span class="muted">每次复跑会调用模型并保留新记录。</span></div><div class="new-run"><label class="field"><span>新 JD：直接在调试台运行完整链路</span><textarea id="new-jd" placeholder="粘贴完整 JD"></textarea></label><button data-action="new-run">运行新 JD</button></div><div class="run-grid"><div class="run-card"><h3>原运行</h3><div id="left-run">加载中</div></div><div class="run-card"><h3>对比运行</h3><div id="right-run">${state.right?'加载中':'复跑后显示在这里'}</div></div></div>`;if(state.left)$('#source-run').value=state.left;await loadRunCards()}
async function loadRunCards(){const targets=[['#left-run',state.left],['#right-run',state.right]];await Promise.all(targets.map(async([selector,id])=>{if(!id)return;try{const data=await get(`/api/debug/run?id=${encodeURIComponent(id)}`);const el=$(selector);if(el)el.innerHTML=runSummary(data)}catch(e){const el=$(selector);if(el)el.textContent=e.message}}))}
function render(){if(!state.flow)return;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view));$('#sidebar').innerHTML=sidebar();$('#inspector').innerHTML=inspector();if(state.view==='flow')$('#workspace').innerHTML=flowCanvas();if(state.view==='index')$('#workspace').innerHTML=indexWorkspace(state.wikiIndex,state.indexPane,state.indexKind);if(state.view==='runs')runsView();if(state.view==='connection')$('#workspace').innerHTML=`<div class="flow-intro"><strong>连接方式</strong><p>浏览器只连接本机服务；本机服务使用你配置的模型接口；经历与简历保存在本机。模型返回 JSON，经程序节点校验后进入下一步。</p><p>当前连接：${esc(state.connection.baseUrl)} → ${esc(state.connection.model)}</p><p>私有 GitHub 仓库用于手动备份资料，在工作台设置中配置；它不参与每次模型推理。</p></div>`}
document.addEventListener('click',async e=>{const edge=e.target.closest('path[data-from]');if(edge){state.selectedLink=state.flow.links.find(x=>x.from===edge.dataset.from&&x.to===edge.dataset.to);render();return}const indexTarget=e.target.closest('[data-index-node],[data-index-relation],[data-index-source]');if(indexTarget){try{if(indexTarget.dataset.indexNode)await selectIndex(indexTarget.dataset.indexNode==='profile_local'?'profile':'node',indexTarget.dataset.indexNode);else if(indexTarget.dataset.indexRelation)await selectIndex('relation',indexTarget.dataset.indexRelation);else await selectIndex('source',indexTarget.dataset.indexSource)}catch(err){toast(`索引读取失败：${err.message}`)}return}const button=e.target.closest('button');if(!button)return;try{if(button.dataset.view){state.view=button.dataset.view;if(state.view==='index'&&!state.wikiIndex)await loadWikiIndex();else render();return}if(button.dataset.indexPane){state.indexPane=button.dataset.indexPane;render();return}if(button.dataset.indexKind){state.indexKind=button.dataset.indexKind;state.indexPane='nodes';render();return}if(button.dataset.indexNode){await selectIndex(button.dataset.indexNode==='profile_local'?'profile':'node',button.dataset.indexNode);return}if(button.dataset.indexRelation){await selectIndex('relation',button.dataset.indexRelation);return}if(button.dataset.indexSource){await selectIndex('source',button.dataset.indexSource);return}if(button.dataset.action==='index-refresh'){await loadWikiIndex(state.wikiIndex?.query||'');toast('索引快照已刷新');return}if(button.dataset.action==='index-search'){const term=$('#index-term').value.trim();await loadWikiIndex(term);return}if(button.dataset.stage){await selectStage(button.dataset.stage);return}if(button.dataset.run){state.view='runs';state.left=button.dataset.run;render();return}if(button.dataset.trace){state.view='runs';state.trace=await get(`/api/debug/trace?id=${encodeURIComponent(button.dataset.trace)}`);state.event=0;render();return}if(button.dataset.event){state.event=Number(button.dataset.event);render();return}if(button.dataset.history){$('#prompt').value=state.prompt.history[Number(button.dataset.history)].prompt;return}if(button.dataset.action==='save-prompt'){state.prompt=await post('/api/debug/prompt',{task:state.selected,prompt:$('#prompt').value});toast('提示词已保存；之后的调用使用新版');render();return}if(button.dataset.action==='reset-prompt'){state.prompt=await post('/api/debug/prompt',{task:state.selected,prompt:state.prompt.default_prompt});toast('已恢复默认提示词');render();return}if(button.dataset.action==='save-workflow'){state.workflow=await post('/api/debug/workflow',{default_retrieval_mode:$('#default-retrieval').value,repair_on_block:$('#repair-on-block').checked});toast('流程规则已保存');render();return}if(button.dataset.action==='save-connection'){state.connection=await post('/api/debug/connection',{baseUrl:$('#base-url').value,model:$('#model-name').value,apiKey:$('#api-key').value});$('#status').textContent=`${state.connection.model} · 已保存`;toast('模型连接设置已保存');render();return}if(button.dataset.action==='test-node'){const input=JSON.parse($('#test-input').value);$('#test-output').textContent='正在调用模型…';const result=await post('/api/debug/test',{task:state.selected,input});state.testOutput=pretty(result.output);state.testInput=pretty(input);await refresh();return}if(button.dataset.action==='new-run'){const jd=$('#new-jd').value.trim();if(!jd)throw Error('请填写 JD');const result=await post('/api/debug/new-run',{jd,mode:$('#retrieval-mode').value,compose:$('#compose-after').checked});state.right=result.id;await refresh();state.view='runs';render();toast('新 JD 运行完成');return}if(button.dataset.action==='replay'){const source=$('#source-run').value,mode=$('#retrieval-mode').value;toast('正在复跑完整大纲链路…');const result=await post('/api/debug/replay',{run_id:source,mode,compose:$('#compose-after').checked});state.left=source;state.right=result.id;await refresh();state.view='runs';render();toast('复跑完成，右侧为新结果');return}if(button.dataset.action==='copy-event'){const event=state.trace.events[state.event];state.view='flow';await selectStage(event.task);state.testInput=pretty(event.input);render();return}}catch(err){toast(`操作失败：${err.message}`);if(button.dataset.action==='test-node'&&$('#test-output'))$('#test-output').textContent=err.message}});
document.addEventListener('change',e=>{if(e.target.id==='source-run')state.left=e.target.value});
refresh().then(()=>selectStage(state.selected)).catch(e=>{toast(`调试台读取失败：${e.message}`);$('#status').textContent='服务未就绪'});

